const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),base=path.join(root,'scripts/client-overrides/public/notebook'),out=path.join(root,'docs/wado-verification-20261027');require(path.join(base,'wado-engine.js'));require(path.join(base,'wado-clues.js'));require(path.join(base,'wado-paper.js'));
const engine=NPWado.create(JSON.parse(fs.readFileSync(path.join(base,'wado-data.json')))),clues=WadoClues.create(JSON.parse(fs.readFileSync(path.join(base,'wado-hints.json')))),all=JSON.parse(fs.readFileSync(path.join(out,'after-puzzles.json'))),chosen=[],seen=new Set();
function add(p,reason){const id=engine.fingerprint(p);if(seen.has(id))return;const hints=clues.all(p).filter(h=>h.grade===3).sort((a,b)=>b.text.length-a.text.length);assert(hints.length);chosen.push({...p,hintChoice:hints[0].id,fixtureReason:reason});seen.add(id);}
for(const level of [1,5,10])for(const count of [2,3,4])add(all.find(p=>p.level===level&&p.count===count),'難度'+level+'・'+count+'語');
for(const p of all.slice().sort((a,b)=>Math.max(...clues.all(b).map(h=>h.text.length))-Math.max(...clues.all(a).map(h=>h.text.length)))){if(chosen.length>=10)break;add(p,'長い文章ヒント');}
const heavy='議識護機観験鑑響織職競難離類議談講警譲';for(const p of all.slice().sort((a,b)=>[...Object.values(b.arms).join('')+b.answer].filter(c=>heavy.includes(c)).length-[...Object.values(a.arms).join('')+a.answer].filter(c=>heavy.includes(c)).length)){if(chosen.length>=12)break;add(p,'画数の多い漢字を含む候補');}
assert.equal(chosen.length,12);const items=chosen.map((p,i)=>({...p,id:'WADO-Q'+String(i+1).padStart(2,'0'),created:Date.UTC(2026,9,27,3,i)}));for(const p of items)engine.validate(p);
const preferences={...WadoPaper.defaults,level:1,wordCount:4,batch:10,kanjiSize:'largest',kanjiWeight:'heavy',spacing:'tight',hint:3,uiSize:'normal',printText:'largest',showId:true,printWeight:'bold'};
const fixture={version:1,items,preferences,play:{active:engine.fingerprint(items[0]),states:{}}};fs.writeFileSync(path.join(out,'print-fixture.json'),JSON.stringify(fixture,null,2)+'\n');fs.writeFileSync(path.join(out,'print-fixture-inventory.json'),JSON.stringify(items.map((p,i)=>({number:i+1,id:p.id,level:p.level,count:p.count,arms:p.arms,example:p.answer,reason:p.fixtureReason,hint:clues.all(p).find(h=>h.id===p.hintChoice)?.text})),null,2)+'\n');console.log('Prepared 12 saved puzzles for mobile and identical A4 exports.');
